import java.util.Scanner;

public class Main {
    static final int MAXN = (1 << 19) | 5;
    static int n, k, p, maxn;
    static int[] popcount_vals = new int[MAXN];
    static int[] f_vals = new int[MAXN];
    static int[][] tmp1_data = new int[20][MAXN];
    static int[][] tmp2_data = new int[20][MAXN];
    static int[][] tmp3_data = new int[20][MAXN];
    static long total_pow;
    static long[][] trans_data = new long[20][MAXN];
    static long[] fact_arr = new long[MAXN];
    static long[] inv_fact_arr = new long[MAXN];

    static long pow_mod(long base, long exp) {
        long res = 1;
        long cur = base % p;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % p;
            cur = (cur * cur) % p;
            exp >>= 1;
        }
        return res;
    }

    static void setup() {
        fact_arr[0] = 1;
        for (int i = 1; i <= maxn; i++)
            fact_arr[i] = (fact_arr[i - 1] * i) % p;
        inv_fact_arr[maxn] = pow_mod(fact_arr[maxn], p - 2);
        for (int i = maxn - 1; i >= 0; i--)
            inv_fact_arr[i] = (inv_fact_arr[i + 1] * (i + 1)) % p;
    }

    static int get_lower_power(int x) {
        int res = 1;
        while (res < x) res <<= 1;
        return res;
    }

    static void FWT_transform(int[] arr, int len, boolean inv) {
        long[] temp = new long[len];
        for (int i = 0; i < len; i++) temp[i] = arr[i];
        for (int step = 1; step < len; step <<= 1) {
            for (int j = 0; j < len; j += (step << 1)) {
                for (int k = j; k < j + step; k++) {
                    long val = temp[k];
                    if (inv) {
                        temp[k + step] -= val;
                    } else {
                        temp[k + step] += val;
                    }
                }
            }
        }
        for (int i = 0; i < len; i++) {
            arr[i] = (int)((temp[i] % p + p) % p);
        }
    }

    static void mod_adjust(long[] x) {
        for (int i = 0; i < x.length; i++) {
            if (x[i] >= total_pow) x[i] -= total_pow;
        }
    }

    static void perform_multiply() {
        for (int i = 0; i <= maxn; i++) {
            for (int j = 0; j < 20; j++) {
                tmp1_data[j][i] = 0;
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_vals[i];
            tmp1_data[c][i] = f_vals[i];
        }
        for (int j = 0; j < 20; j++) {
            FWT_transform(tmp1_data[j], maxn + 1, false);
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= maxn; s++) {
                    long val = (long)tmp1_data[q][s] * tmp2_data[l][s];
                    trans_data[q + l][s] += val;
                }
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans_data[q][s] = ((trans_data[q][s] % p) + p) % p;
            }
        }
        for (int q = 0; q <= 19; q++) {
            long[] temp = new long[maxn + 1];
            for (int s = 0; s <= maxn; s++) {
                temp[s] = trans_data[q][s];
            }
            FWT_transform(temp, maxn + 1, true);
            for (int s = 0; s <= maxn; s++) {
                tmp3_data[q][s] = (int)(temp[s] % p);
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                f_vals[s] = tmp3_data[popcount_vals[s]][s];
            }
        }
    }

    static void perform_alt_multiply() {
        long[][] temp = new long[20][maxn + 1];
        for (int i = 0; i <= 19; i++) {
            for (int s = 0; s <= maxn; s++) {
                trans_data[i][s] = 0;
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= maxn; s++) {
                    long val = (long)tmp2_data[q][s] * tmp2_data[l][s];
                    trans_data[q + l][s] += val;
                }
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans_data[q][s] = ((trans_data[q][s] % p) + p) % p;
            }
        }
        for (int i = 0; i <= 19; i++) {
            long[] tempArr = new long[maxn + 1];
            for (int s = 0; s <= maxn; s++) {
                tempArr[s] = trans_data[i][s];
            }
            FWT_transform(tempArr, maxn + 1, true);
            for (int s = 0; s <= maxn; s++) {
                tmp2_data[i][s] = (int)(tempArr[s] % p);
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_vals[i];
            for (int q = 0; q <= 19; q++) {
                long[] tempArr = new long[maxn + 1];
                for (int s = 0; s <= maxn; s++) {
                    tempArr[s] = tmp2_data[q][s];
                }
                FWT_transform(tempArr, maxn + 1, false);
                for (int s = 0; s <= maxn; s++) {
                    tmp2_data[q][s] = (int)(tempArr[s] % p);
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();
        total_pow = (long) p * p;
        if ((n & 1) == 1) {
            System.out.println(pow_mod(k, n));
            sc.close();
            return;
        }
        f_vals[0] = 1;
        maxn = get_lower_power(n + 1) - 1;
        setup();
        for (int i = 0; i <= maxn; i++) {
            popcount_vals[i] = Integer.bitCount(i);
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_vals[i];
            tmp2_data[c][i] = (int)inv_fact_arr[i];
        }
        for (int i = 0; i < 20; i++) {
            FWT_transform(tmp2_data[i], maxn + 1, false);
        }
        int res_k = k;
        while (res_k > 0) {
            if ((res_k & 1) == 1) perform_multiply();
            res_k >>= 1;
            if (res_k > 0) perform_alt_multiply();
        }
        long result = (pow_mod(k, n) - (fact_arr[n] * f_vals[n] % p) + p) % p;
        System.out.println(result);
        sc.close();
    }
}

